<script setup lang="ts">import {ref,computed,onMounted} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {catalogApi} from '../api/catalog';import {useTask} from '../hooks/useTask';import {clock} from '../utils/format';const p=defineProps<{studies:any[];traces:any[];user:any;reloadCatalog:()=>Promise<void>}>(),id=ref(0),drafts=ref<Record<number,string>>({}),batches=ref<any[]>([]),current=ref<any|null>(null),task=useTask(),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),rows=computed(()=>p.traces.filter(t=>t.study_id===study.value?.id)),items=computed(()=>rows.value.filter(t=>(drafts.value[t.id]||'').trim()).map(t=>({trace_id:t.id,tokens:drafts.value[t.id].trim().split(/\s+/)})));async function reload(){batches.value=await catalogApi.corrections()}async function sync(){await Promise.all([reload(),p.reloadCatalog()]);if(current.value)current.value=batches.value.find(b=>b.id===current.value.id)||current.value}onMounted(reload);async function preview(){await task.act(async()=>{const b=await catalogApi.previewCorrections({study_id:study.value.id,items:items.value});await reload();current.value=b;drafts.value={}},'预览已生成：确认后整批落底稿，放弃请直接忽略')}async function confirm(b:any){task.state.busy=true;task.state.error='';task.state.message='';try{const r=await catalogApi.confirmCorrections(b.id);current.value=r;task.state.message=r.duplicated?'该预览此前已确认，本次未重复变更':'整批纠错已应用，底稿版本已整批推进'}catch(e){task.state.error=e.message}finally{task.state.busy=false;await sync()}}</script><template><PageTitle index="03" title="整批纠错先预览，确认才落底稿。" description="预览冻结每条改前版本；确认时任一条已被他人改动，整批拒绝且未冲突条目同样保持原样。"/><label>纠错研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value);drafts={}"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="study">{{study.filename}} / 观测码{{study.symbols.join(' / ')}} / 已填写{{items.length}}条纠错</p><div class="source-layout"><section><h2>观测底稿 / 留空不纠错</h2><Table :headers="['轨迹编号','版本','当前观测片段','新观测码']"><tr v-for="t in rows" :key="t.id"><td>{{t.reference}}</td><td>r{{t.revision}}</td><td class="tokens">{{t.tokens.slice(0,24).join(' ')}}{{t.tokens.length>24?' …':''}}</td><td><input v-if="user.role!=='viewer'" v-model="drafts[t.id]" placeholder="空格分隔观测码"/><span v-else>—</span></td></tr></Table><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy||!items.length" @click="preview">生成整批预览（{{items.length}}条）→</button></section><section v-if="current" class="input-panel"><small>BATCH #{{current.id}} / {{current.created_by}}</small><h2>改前 / 改后对照</h2><Table :headers="['轨迹编号','改前观测','改后观测']"><tr v-for="i in current.items" :key="i.trace_id"><td>{{i.reference}}<small>基于 r{{i.base_revision}}</small></td><td class="tokens">{{i.before.join(' ')}}</td><td class="tokens">{{i.after.join(' ')}}</td></tr></Table><template v-if="current.status==='pending'"><p>确认后整批写入；任一轨迹版本被他人推进则整批拒绝。</p><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy" @click="confirm(current)">确认整批应用 →</button></template><template v-else-if="current.status==='conflicted'&&current.conflicts"><p>整批已拒绝，以下条目被他人改动；其余条目也保持原样：</p><Table :headers="['轨迹编号','预览版本','当前版本','当前观测']"><tr v-for="c in current.conflicts" :key="c.trace_id"><td>{{c.reference}}</td><td>r{{c.base_revision}}</td><td>{{c.current_revision===null?'已删除':'r'+c.current_revision}}</td><td class="tokens">{{c.current_tokens?c.current_tokens.join(' '):'—'}}</td></tr></Table></template><p v-else-if="current.status==='applied'">已由 {{current.confirmed_by}} 于 {{clock(current.confirmed_at)}} 整批应用。</p></section></div><Notice v-bind="task.state"/><section class="section"><h2>纠错批次记录</h2><Table :headers="['批次','状态','条目','创建','确认','操作']"><tr v-for="b in batches" :key="b.id"><td>#{{b.id}}</td><td><Status :value="b.status"/></td><td>{{b.items.length}}</td><td>{{b.created_by}}<small>{{clock(b.created_at)}}</small></td><td>{{b.confirmed_by||'—'}}<small v-if="b.confirmed_at">{{clock(b.confirmed_at)}}</small></td><td><button @click="current=b">查看</button><button v-if="b.status==='pending'&&user.role!=='viewer'" :disabled="task.state.busy" @click="confirm(b)">确认</button></td></tr></Table></section></template>
